command:
// ==========================================
// ⚙️ LUNAS WIRKUNG: ZIELSCHEIBE (Ausführung)
// ==========================================

(async () => {
    // --- 1. FRAMEWORK LADEN ---
    let fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn");
    if (fwMacro) { await fwMacro.execute(); }

    const DSK_FW = globalThis.DSK || DSK;
    if (typeof DSK_FW === "undefined") return ui.notifications.error("Luna sagt 🌙: Framework fehlt!");

    const gabenName = "Zielscheibe";
    const ahne = "Zerzal";
    const iconBild = DSK_FW.Symbol(ahne);
    const maxReichweite = 16;

    const getOwners = (act) => Object.entries(act?.ownership || {}).filter(([id, lvl]) => lvl === 3 && id !== "default").map(([id]) => id);

    // --- 2. CASTER ERMITTELN ---
    let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character;
    if (!casterActor) casterActor = game.actors.find(a => a.getFlag("world", "letzteGabenQS") !== undefined);
    if (!casterActor) {
        for (let t of canvas.tokens.placeables) {
            if (t.actor && t.actor.getFlag("world", "letzteGabenQS") !== undefined) { casterActor = t.actor; break; }
        }
    }
    if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Kein Wirkender gefunden!");

    let casterToken = casterActor.getActiveTokens()[0] || canvas.tokens.controlled[0];
    if (!casterToken) return ui.notifications.warn("Luna sagt 🌙: Der Wirkende braucht einen Token auf der Szene für die Entfernungsberechnung!");

    const qs = Number(casterActor.getFlag("world", "letzteGabenQS") || 1);
    const alteMessageId = casterActor.getFlag("world", "letzteGabenMessageId");
    let ownerIds = new Set(game.users.filter(u => u.isGM).map(u => u.id));
    getOwners(casterActor).forEach(id => ownerIds.add(id));

    // --- 3. BERECHNUNGEN ---
    const kampfRunden = qs * 2;
    const thinStyle = 'style="font-weight: 300; font-size: 0.9em; opacity: 0.8;"';
    const dauerCalc = `<span ${thinStyle}>(${qs} QS x 2)</span>`;

    // --- 4. WEIßER SPEER PRÜFUNG ---
    const speerEffekt = casterActor.effects.find(e => (e.name || e.label || "").toLowerCase().includes("weißer speer"));
    if (!speerEffekt) {
        const fehlschlagHtml = `
            <div style="font-family: 'Signika', sans-serif;">
                ${DSK_FW.UI.Header(gabenName, iconBild)}
                <div class="dskbox2" style="margin-top:10px;">
                    <p style="text-align:center; color:#B30000; font-weight:bold; font-size: 1.1em; margin-bottom: 5px;">Fehlschlag!</p>
                    <p style="text-align:center; margin-top: 0;">Die Gabe verpufft wirkungslos, da der <b>Weiße Speer</b> nicht aktiv ist.</p>
                </div>
            </div>
        `;
        let msg = alteMessageId ? game.messages.get(alteMessageId) : null;
        if (msg) {
            await msg.update({ content: fehlschlagHtml });
        } else {
            await ChatMessage.create({
                speaker: { alias: "System" },
                whisper: Array.from(ownerIds).filter(id => game.users.get(id)),
                content: fehlschlagHtml
            });
        }
        await casterActor.unsetFlag("world", "letzteGabenQS");
        await casterActor.unsetFlag("world", "letzteGabenMessageId");
        return;
    }

    const effIcon = speerEffekt.img || speerEffekt.icon || iconBild;

    // --- 5. ZIELE HOLEN ---
    const targets = Array.from(game.user.targets);
    if (targets.length === 0) return ui.notifications.warn("Luna sagt 🌙: Bitte wähle ein Ziel per Target aus!");

    // --- 6. EFFEKTE ANWENDEN ---
    const erfolge = [];
    const fehler = [];

    for (let t of targets) {
        if (!t.actor) continue;

        const distanz = Math.round(DSK_FW.Geometrie.Distanz(casterToken, t) * 10) / 10;
        if (distanz > maxReichweite) {
            fehler.push({ name: t.name, grund: "Zu weit weg" });
            continue;
        }

        let istLebewesen = DSK_FW.Effekt.CheckTarget(t.actor, "lebewesen") ||
                           DSK_FW.Effekt.CheckTarget(t.actor, "erwachte") ||
                           t.actor.type === "character" ||
                           t.actor.type === "npc";

        if (DSK_FW.Effekt.CheckTarget(t.actor, "geist") || DSK_FW.Effekt.CheckTarget(t.actor, "untot")) {
            istLebewesen = false;
        }

        if (!istLebewesen) {
            fehler.push({ name: t.name, grund: "Kein Lebewesen" });
            continue;
        }

        // Erfolg
        const finalEffektName = `${gabenName} (${ahne}) - ${t.name}`;
        const targetBeschreibung = `Das Zerzalkind erklärt ${t.name} zu seiner Beute. Bei Angriffen auf dieses Ziel mit dem Weißen Speer ist der Angriffswert um ${qs} (QS) erhöht.`;

        if (DSK_FW.EffektEnde) {
            DSK_FW.EffektEnde.Register("zerzalZielscheibe", finalEffektName, "Du verlierst deine Beute aus dem Fokus. Dein Angriff sinkt wieder auf den Normalwert.");
        }

        const effectData = {
            name: finalEffektName,
            icon: effIcon,
            description: targetBeschreibung,
            duration: { rounds: kampfRunden },
            changes: [
                { key: "system.rangeStats.attack", mode: 2, value: `${qs}`, priority: 20 },
                { key: "system.meleeStats.attack", mode: 2, value: `${qs}`, priority: 20 }
            ],
            flags: {
                core: { statusId: "zerzalZielscheibe" },
                dsk: { ahne: "zerzal", casterUuid: casterActor.uuid }
            }
        };

        // Alten Effekt löschen, falls vorhanden
        let alterEffekt = casterActor.effects.find(e => (e.name || e.label) === finalEffektName);
        if (alterEffekt) await alterEffekt.delete();

        // Bonus wird dem Wirkenden gegeben!
        await casterActor.createEmbeddedDocuments("ActiveEffect", [effectData]);
        erfolge.push(t.name);
    }

    // --- 7. FLAG-CLEANUP ---
    if (erfolge.length > 0 || fehler.length > 0) {
        await casterActor.unsetFlag("world", "letzteGabenQS");
        await casterActor.unsetFlag("world", "letzteGabenMessageId");
    }

    // --- 8. CHAT-KARTE ---
    targets.forEach(t => {
        if(t?.actor) Object.entries(t.actor.ownership || {}).filter(([id, lvl]) => lvl === 3).forEach(([id]) => ownerIds.add(id));
    });

    const erfolgHtml = erfolge.length > 0 
        ? `<div style="margin-top: 10px; margin-bottom: 10px;">
               <p style="margin-bottom: 5px;"><span style="color:#18940F; font-weight:bold;">Beute markiert:</span></p>
               <ul class="dsklist" style="margin-top:0; font-weight:normal; color: #000;">
                   ${erfolge.map(n => `<li>${n}</li>`).join("")}
               </ul>
           </div>` : ``;

    const fehlschlagHtml = fehler.length > 0
        ? `<div style="margin-top: 10px; margin-bottom: 10px;">
               <p style="margin-bottom: 5px;"><span style="color:#B30000; font-weight:bold;">Fehlschlag:</span></p>
               <ul class="dsklist" style="margin-top:0; font-weight:normal; color: #000;">
                   ${fehler.map(f => `<li>${f.name} (${f.grund})</li>`).join("")}
               </ul>
           </div>` : ``;

    const cardContent = `
        <div style="font-family: 'Signika', sans-serif;">
            ${DSK_FW.UI.Header(gabenName, iconBild)}
            <div class="dskbox2" style="margin-top:10px;">
                <p style="margin-bottom: 8px;"><b>Gabenwirkung:</b></p>
                <p style="margin-top:0; text-align: justify;">Das Zerzalkind erklärt ein Ziel zu seiner Beute. Bei Angriffen auf dieses Ziel, die mit dem <b>Weißen Speer</b> ausgeführt werden, ist der Angriffswert um <b>${qs} (QS)</b> erhöht.</p>
                ${erfolgHtml}
                ${fehlschlagHtml}
                <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                <p style="text-align:center; font-weight:bold; margin-bottom: 0;">
                    Wirkungsdauer:<br>${kampfRunden} Kampfrunden ${dauerCalc}
                </p>
            </div>
        </div>
    `;

    let msg = alteMessageId ? game.messages.get(alteMessageId) : null;
    if (msg) {
        await msg.update({ content: cardContent });
    } else {
        const neueMsg = await ChatMessage.create({
            speaker: { alias: "System" },
            whisper: Array.from(ownerIds).filter(id => game.users.get(id)),
            content: cardContent
        });
        if (neueMsg && erfolge.length === 0 && fehler.length === 0) {
            await casterActor.setFlag("world", "letzteGabenMessageId", neueMsg.id);
        }
    }
})();
